   832  static void test_genkeypair(const uint8_t *data, size_t size)
   833  {
   834          CK_SESSION_HANDLE session;
   835          CK_OBJECT_HANDLE  hPublicKey;
   836          CK_OBJECT_HANDLE  hPrivateKey;
   837          CK_MECHANISM      mech = {0, NULL_PTR, 0};
   838          uint8_t           login_type = CKU_USER;
   839          char             *pin = NULL;
   840          CK_OBJECT_CLASS   pubkey_class = CKO_PUBLIC_KEY;
   841          CK_OBJECT_CLASS   privkey_class = CKO_PRIVATE_KEY;
   842          int               n_pubkey_attr = 2;
   843          int               n_privkey_attr = 2;
   844          CK_ATTRIBUTE     *publicKeyTemplate = NULL;
   845          CK_ATTRIBUTE     *privateKeyTemplate = NULL;
   846
   847          /* Process options*/
   848          if (set_mechanism(&data, &size, &mech) || size < 3)
   849                  goto end;
   850          login_type = data[0];
   851          data++; size--;
   852          if (!(pin = extract_word(&data, &size)))
   853                  goto end;
   854
   855          if (fill_key_template(&publicKeyTemplate, &n_pubkey_attr, &data, &size, &pubkey_class, true) != 0
   856                  || fill_key_template(&privateKeyTemplate, &n_privkey_attr, &data, &size, &privkey_class, true) != 0)
   857                  goto end;
   858
   859          /* Initialize */
   860          if (fuzz_pkcs11_initialize(data, size, NULL, &session) != CKR_OK)
   861                  goto end;
   862
   863          p11->C_Login(session, login_type, (CK_UTF8CHAR *) pin, strlen(pin));
   864          p11->C_GenerateKeyPair(session, &mech, publicKeyTemplate, n_pubkey_attr,
   865                                                     privateKeyTemplate, n_privkey_attr,
   866                                                     &hPublicKey, &hPrivateKey);
   867          p11->C_CloseSession(session);
   868          p11->C_Finalize(NULL);
   869
   870  end:
   871          free(pin);
   872          free(privateKeyTemplate);
   873          free(publicKeyTemplate);
   874  }
